<script setup lang="ts">import{onMounted,ref}from'vue';const rows=ref<any[]>([]),error=ref('');onMounted(async()=>{const r=await fetch('/api/visitor/admin/registrations',{headers:{Authorization:sessionStorage.getItem('visitor-authorization')||''}});if(r.ok)rows.value=await r.json();else error.value='加载失败'});</script>
<template><header><p class="eyebrow">ADMIN</p><h2>登记查询</h2></header><p v-if="error" class="error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>编号</th><th>姓名</th><th>手机号</th><th>被访部门</th><th>事由</th><th>登记时间</th></tr></thead><tbody><tr v-for="r in rows" :key="r.visitId"><td>{{r.visitId}}</td><td>{{r.visitorName}}</td><td>{{r.mobile}}</td><td>{{r.hostDepartment}}</td><td>{{r.visitReason}}</td><td>{{r.registeredAt}}</td></tr></tbody></table></div></template>
